// <auto-generated/>
using System;
using System.Collections;
using System.Data;
using System.Text;
using DNAide.Core;
using DNAide.Data;
using DNAide.Utils;
using DNAide.Web;
using Sunplus.Accounting.Business.Report;
using Sunplus.Accounting.Core.Web;
using Sunplus.Accounting.DataAccess.IBCDLL.Accounting;
using Sunplus.Accounting.DataAccess.Report;

public partial class Report_BingoDetail : PageBase
{
    #region varialbes
    protected StringBuilder html = new StringBuilder();
    #endregion

    protected void Page_Load(object sender, EventArgs e)
    {
        Title = Reports.Title;
        var bettype = Request["bettype"];
        var wldate = CastAide.AsDateTime(Request["wldate"]);
        html.Append(BingoWLReport(bettype, wldate));

        if (Request["type"] == "Direct")
        {
            var script = "<script type ='text/javascript'>";
            script += "parent.showProgressBar(false);";
            script += "</script>";
            Response.Write(script);
        }
    }

    string BingoWLReport(string betType, DateTime wlDate)
    {
        var tpl = WebUtils.LoadTemplate("WinLost/BingoWLDetail.htm");
        var tplContent = TemplateHandler.CopyBlock(tpl, "content");
        var rows = new StringBuilder();
        try
        {
            TemplateHandler.Assign(ref tpl, "bettype", betType);
            TemplateHandler.Assign(ref tpl, "wldate", wlDate.ToShortDateString());
            #region private variables
            var db = Request["db"];
            db = (string.IsNullOrEmpty(db)) ? "rep" : db;
            DbResult rs = null;

            var movebetsday = ReportUtils.BalanceUp.MoveBetsDay;
            //rs = wlDate <= movebetsday ? MatchWinLostReport.WinlostCasino_Details_14(wlDate) :
            //    MatchWinLostReport.WinlostCasino_Details(wlDate, db);

            rs = wlDate <= movebetsday ? MatchWinLostReport.WinLostBingo_Detail_14(wlDate) :
                MatchWinLostReport.WinLostBingo_Details(wlDate, db);

            var dt = rs.ResultSet.Tables[0];

            var dv = dt.DefaultView;
            dv.Sort = "Currency asc";

            var dtBingo = dv.ToTable();
            var index = 0;
            var rowEvenOdd = "#dfeaff";
            double turnOverTotal = 0, winLostTotal = 0, posTotal = 0, commTotal = 0, lineTotal = 0;
            #endregion

            #region get data
            foreach (DataRow dr in dtBingo.Rows)
            {
                index++;
                var row = tplContent;
                
                turnOverTotal += CastAide.AsDouble(dr["Turnover"]);
                winLostTotal += CastAide.AsDouble(dr["winlost"]);
                posTotal += CastAide.AsDouble(dr["pos"]);
                commTotal += CastAide.AsDouble(dr["comm"]);
                lineTotal += CastAide.AsDouble(dr["LineTotal"]);

                if (index > 1) TemplateHandler.RemoveBlock(ref row, "Bettype");
                rowEvenOdd = rowEvenOdd.Equals("#e8ebd3") ? "#dfeaff" : "#e8ebd3";
                TemplateHandler.Assign(ref row, "bgcolor", "style='background-color:" + rowEvenOdd + "'");
                
                TemplateHandler.Assign(ref row, "align", "c");
                TemplateHandler.Assign(ref row, "Bettype", betType);
                TemplateHandler.Assign(ref row, "Currency", dr["CurrencyName"]);
                TemplateHandler.Assign(ref row, "turnover", NumberFormat.DecFormat(dr["turnover"], 2));
                TemplateHandler.Assign(ref row, "winlost", NumberFormat.DecFormat(dr["winlost"], 2));
                TemplateHandler.Assign(ref row, "pos", NumberFormat.DecFormat(dr["pos"], 2));
                TemplateHandler.Assign(ref row, "comm", NumberFormat.DecFormat(dr["comm"], 2));
                TemplateHandler.Assign(ref row, "linetotal", NumberFormat.DecFormat(dr["linetotal"], 2));
                TemplateHandler.Assign(ref row, "{report-row}", "b");
                rows.Append(row);
            }
            
            #endregion

            #region Toltal of bettype
            var rowTotal = tplContent;
            rows.Replace("{rowspan}", index.ToString());
            rowEvenOdd = "#d6efba";
            TemplateHandler.Assign(ref rowTotal, "report-row", "footer1");
            TemplateHandler.Assign(ref rowTotal, "bgcolor", "bgcolor='" + rowEvenOdd + "'");
            TemplateHandler.RemoveBlock(ref rowTotal, "Bettype");
            TemplateHandler.ReplaceBlock(ref rowTotal, "Currency", "<td colspan='2' align='center'>Grand Total</td>");
            TotalRows(ref rowTotal, turnOverTotal, winLostTotal, posTotal, commTotal, lineTotal);
            rows.Append(rowTotal);
            #endregion

            TemplateHandler.ReplaceBlock(ref tpl, "content", rows.ToString());
            if (Request["IsExport"] == "1") Reports.ExportToExcel(tpl, betType + "_" + wlDate.ToShortDateString());
        }
        catch(Exception ex)
        {
            tpl = "<font color='red'><b>" + ex.Message + "</b></font>";
        }
        return tpl;
    }

    static void TotalRows(ref string row, double turnOverTotal, double winLostTotal, double posTotal, double commTotal, double lineTotal)
    {
        TemplateHandler.Assign(ref row, "align", "c");
        TemplateHandler.Assign(ref row, "Currency", "Bingo Total");
        TemplateHandler.Assign(ref row, "turnover", NumberFormat.DecFormat(turnOverTotal, 2));
        TemplateHandler.Assign(ref row, "winlost", NumberFormat.DecFormat(winLostTotal, 2));
        TemplateHandler.Assign(ref row, "pos", NumberFormat.DecFormat(posTotal, 2));
        TemplateHandler.Assign(ref row, "comm", NumberFormat.DecFormat(commTotal, 2));
        TemplateHandler.Assign(ref row, "linetotal", NumberFormat.DecFormat(lineTotal, 2));
    }
}
